/**
 * "Blocked by" links between issues: authorization, cycle rejection, the open-blocker view the completion gate relies on, and the `issue_unblocked` reaction.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, notify, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueDependencyRepo from "@/server/repositories/issue-dependency-repository";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import {
  CLOSED_ISSUE_STATUSES,
  type Issue,
  type IssueDependency,
  type IssueStatus,
} from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised by the completion gate when `done` is requested while blockers are open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.length} open issue(s)`);
    this.name = "IssueBlockedError";
  }
}

/** A link that would make an issue (transitively) block itself. */
class CircularBlockerError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly issueId: IssueId, readonly blockerId: IssueId) {
    super(`Issue ${blockerId} cannot block ${issueId}: it would create a cycle`);
    this.name = "CircularBlockerError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open = live and not `done`/`canceled`. Everything else is closed. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

/** Walks the "blocked by" edges from `start`; true if `target` is reachable. */
async function reachesBlocker(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([start]);
  const queue: IssueId[] = [start];

  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    if (current === target) return true;

    for (const next of await issueDependencyRepo.listBlockerIds(orgId, current)) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return false;
}

async function hasOpenBlocker(orgId: OrgId, issueId: IssueId): Promise<boolean> {
  for (const blockerId of await issueDependencyRepo.listBlockerIds(orgId, issueId)) {
    const blocker = await issueRepo.findIssueById(orgId, blockerId);
    if (blocker && isOpen(blocker)) return true;
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
