import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as depService from "@/server/services/issue-dependency-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
const EPOCH = "1970-01-01T00:00:00.000Z" as IsoTimestamp;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("depsmoke");
  registerEventHandlers();
});
afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function mk(title: string, assigneeId: string | null = t.userIds.viewer) {
  return issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, t.project.id, { title, assigneeId } as never),
  );
}

describe("issue dependencies smoke", () => {
  it("links, dedupes, rejects self/cycle, lists, and gates done", async () => {
    const a = await mk("A");
    const b = await mk("B");
    const c = await mk("C");
    const link = await depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(link.blockerId).toBe(b.id);
    const again = await depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(again.createdAt).toBe(link.createdAt);
    await expect(depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: a.id })).rejects.toThrow();
    await expect(depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: b.id, blockerId: c.id });
    await expect(depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: a.id })).rejects.toThrow();
    await expect(depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: "nope" as IssueId })).rejects.toThrow();
    const blockers = await depService.listBlockers(t.actors.member, t.org.id, a.id);
    expect(blockers.map((i) => i.id)).toEqual([b.id]);

    await expect(issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: a.id, status: "done" }))
      .rejects.toMatchObject({ code: "conflict", blockerIds: [b.id] });
    expect((await issueService.getIssue(t.actors.member, t.org.id, a.id)).issue.status).toBe("backlog");

    expect(await depService.removeBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(true);
    expect(await depService.removeBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(false);
  });

  it("notifies assignee when blocker closes", async () => {
    const blocked = await mk("Blocked");
    const blocker = await mk("Blocker");
    await depService.addBlocker(t.actors.member, { orgId: t.org.id, issueId: blocked.id, blockerId: blocker.id });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: blocker.id, status: "canceled" });
    const got = await notificationRepo.listUnreadSince(t.org.id, t.userIds.viewer, EPOCH);
    const mine = got.filter((n) => n.kind === "issue_unblocked");
    expect(mine).toHaveLength(1);
    expect(mine[0].href).toBe(`/issues/${blocked.id}`);
    expect(mine[0].actorId).toBe(t.userIds.member);
    // closed -> closed should not notify again
    await issueService.archiveIssue(t.actors.member, t.org.id, blocker.id);
    const after = (await notificationRepo.listUnreadSince(t.org.id, t.userIds.viewer, EPOCH)).filter((n) => n.kind === "issue_unblocked");
    expect(after).toHaveLength(1);
  });
});
